import{PARKS,SUPPLIES}from"./wildlife-data.js";export class WildlifeEngine{constructor(){this.listeners=[],this.parks=JSON.parse(JSON.stringify(PARKS)),this.currentParkIndex=0,this.resetState()}resetState(){const t=this.parks[this.currentParkIndex],e=t.mapSize;this.state={park:t,player:{x:0,y:0,health:100},inventory:{"Medical Kit":1,"Tracking Tag":0,"Ranger Equipment":0},xp:0,coins:0,animal:{x:e-1,y:e-1,...t.animal,rescued:!1},poachers:this.generatePoachers(t.difficulty,e),traps:this.generateTraps(t.difficulty+2,e),supplies:this.generateSupplies(t.difficulty+1,e),gridSize:e,gameOver:!1,gameWon:!1,message:"Welcome to "+t.name},this.timer&&clearInterval(this.timer),this.timer=setInterval(()=>this.tick(),1e3),this.notifyListeners()}generatePoachers(t,e){let s=[];for(let i=0;i<t;i++)s.push({x:Math.floor(Math.random()*(e-2))+1,y:Math.floor(Math.random()*(e-2))+1,direction:Math.random()>.5?"h":"v",speed:1});return s}generateTraps(t,e){let s=[];for(let i=0;i<t;i++)s.push({id:`trap-${i}`,x:Math.floor(Math.random()*(e-2))+1,y:Math.floor(Math.random()*(e-2))+1,active:!0});return s}generateSupplies(t,e){let s=[];for(let i=0;i<t;i++)s.push({id:`supply-${i}`,x:Math.floor(Math.random()*(e-2))+1,y:Math.floor(Math.random()*(e-2))+1,type:SUPPLIES[Math.floor(Math.random()*SUPPLIES.length)],active:!0});return s}subscribe(t){return this.listeners.push(t),()=>this.listeners=this.listeners.filter(e=>e!==t)}notifyListeners(){this.listeners.forEach(t=>t(this.state,this.parks))}movePlayer(t,e){if(this.state.gameOver)return;let s=this.state.player.x+t,i=this.state.player.y+e;s>=0&&s<this.state.gridSize&&i>=0&&i<this.state.gridSize&&(this.state.player.x=s,this.state.player.y=i,this.checkCollisions(),this.notifyListeners())}checkCollisions(){const{player:t,animal:e,traps:s,supplies:i,poachers:a}=this.state;i.forEach(e=>{e.active&&e.x===t.x&&e.y===t.y&&(e.active=!1,this.state.inventory[e.type]++,this.state.xp+=50,this.state.message=`Collected ${e.type}! (+50 XP)`)}),s.forEach(e=>{e.active&&e.x===t.x&&e.y===t.y&&(this.state.inventory["Ranger Equipment"]>0?(e.active=!1,this.state.inventory["Ranger Equipment"]--,this.state.xp+=100,this.state.message="Disabled a trap using Ranger Equipment! (+100 XP)"):(e.active=!1,this.state.player.health-=25,this.state.xp-=100,this.state.message="Ouch! You stepped on a trap. (-25 Health, -100 XP)"))}),a.forEach(e=>{e.x===t.x&&e.y===t.y&&this.endGame(!1,"Caught by a poacher! Mission Failed.")}),e.x!==t.x||e.y!==t.y||e.rescued||(this.state.inventory["Medical Kit"]>0?(this.state.inventory["Medical Kit"]--,e.rescued=!0,e.health=100,this.state.xp+=500,this.state.coins+=1e3,this.endGame(!0,`Rescued the ${e.name}! (+500 XP, +1000 Coins)`),this.unlockNextPark()):this.state.message="You need a Medical Kit to rescue the animal!"),this.state.player.health<=0&&this.endGame(!1,"You lost all your health! Mission Failed.")}tick(){this.state.gameOver||(this.state.poachers.forEach(t=>{"h"===t.direction?(t.x+=t.speed,(t.x<=0||t.x>=this.state.gridSize-1)&&(t.speed*=-1)):(t.y+=t.speed,(t.y<=0||t.y>=this.state.gridSize-1)&&(t.speed*=-1))}),this.checkCollisions(),this.notifyListeners())}endGame(t,e){this.state.gameOver=!0,this.state.gameWon=t,this.state.message=e,this.timer&&clearInterval(this.timer)}unlockNextPark(){this.currentParkIndex+1<this.parks.length&&(this.parks[this.currentParkIndex+1].unlocked=!0)}loadPark(t){this.parks[t].unlocked&&(this.currentParkIndex=t,this.resetState())}}export const wildlifeEngine=new WildlifeEngine;